package cli

import (
	"testing"
	"time"
)

func TestReachableCheckpointRoutesToDefaultBranchFolder(t *testing.T) {
	selected := map[string]selectedSession{}
	destinations := checkpointBranchDestinations{
		DefaultBranch: "main",
		DefaultCheckpointIDs: map[string]struct{}{
			"aaa111aaa111": {},
		},
	}

	addSelectedSession(selected, selectedSession{
		CheckpointID: "aaa111aaa111",
		SessionID:    "session-one",
		Branch:       "feature/already-merged",
		CreatedAt:    time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC),
	}, destinations)

	session, ok := selected[selectedSessionKey("main", "session-one")]
	if !ok {
		t.Fatalf("reachable checkpoint was not routed to the default branch folder: %+v", selected)
	}
	if session.Branch != "main" {
		t.Fatalf("destination branch = %q, want main", session.Branch)
	}
	if session.SourceBranch != "feature/already-merged" {
		t.Fatalf("source branch = %q, want the original feature branch preserved", session.SourceBranch)
	}
	if _, leaked := selected[selectedSessionKey("feature/already-merged", "session-one")]; leaked {
		t.Fatalf("reachable checkpoint must not also land in its recorded feature-branch folder: %+v", selected)
	}
}
